WITH flattened AS (SELECT id, customer_id, created_at, elem.product_id FROM carts LATERAL VIEW OUTER EXPLODE(items) x AS elem) SELECT CASE WHEN product_id >= 11 THEN 'LARGE' ELSE 'SMALL' END AS product_id_tier, APPROX_PERCENTILE(product_id, ARRAY(0.25, 0.5, 0.75)) AS product_id_quartiles, COUNT(*) AS event_count, MIN(product_id) AS min_product_id FROM flattened GROUP BY CASE WHEN product_id >= 11 THEN 'LARGE' ELSE 'SMALL' END HAVING min_product_id >= 0 ORDER BY event_count;
